function fence(parent,[x1,y1,x2,y2]){const g=node('g',{'data-goat-fence':'','pointer-events':'none'},parent),a=iso(x1,y1),b=iso(x2,y2);for(const h of [12,25])node('path',{d:`M${a.x},${a.y-h} L${b.x},${b.y-h}`,stroke:'#a18d62','stroke-width':4},g);for(let i=0;i<7;i++){const p=iso(x1+(x2-x1)*i/6,y1+(y2-y1)*i/6);node('path',{d:`M${p.x},${p.y+3} v-34`,stroke:'#bca779','stroke-width':6,'stroke-linecap':'round'},g);}}
/** @param {Element} parent @param {import('./goat-scene-snapshot.js').GoatRanchSnapshot} snapshot */
function shelter(parent,snapshot){const [a,b,c,d]=corners(L.shelter),h=54,g=node('g',{'data-goat-shelter':'goat.shelter.1','data-shelter-level':snapshot.level,'data-cleanliness':snapshot.cleanliness,'data-goat-object':'shelter','aria-label':t('goatShelter')},parent);node('polygon',{points:points([a,b,c,d]),fill:'#ddc795',stroke:'#bda574'},g);if(snapshot.cleanliness<80)node('ellipse',{cx:(c.x+d.x)/2,cy:(c.y+d.y)/2+7,rx:18,ry:6,fill:'#a38b62','data-goat-dirt':''},g);for(const [p,q]of [[b,c],[c,d]]){node('polygon',{points:points([p,q,{x:q.x,y:q.y-h},{x:p.x,y:p.y-h}]),fill:p===b?'#b49c70':'#cdb383',stroke:'#9c8159','stroke-width':2},g);}const center={x:(c.x+d.x)/2,y:(c.y+d.y)/2};node('path',{d:`M${center.x-17},${center.y} v-37 h34 v37`,fill:'#485d43',stroke:'#9c8159','stroke-width':3},g);node('polygon',{points:points([a,b,c,d].map(p=>({x:p.x,y:p.y-h}))),fill:'#9c6b4c',stroke:'#79563e','stroke-width':3},g);for(let i=1;i<5;i++){const r=i/5,p={x:a.x+(d.x-a.x)*r,y:a.y+(d.y-a.y)*r-h},q={x:b.x+(c.x-b.x)*r,y:b.y+(c.y-b.y)*r-h};node('path',{d:`M${p.x},${p.y} L${q.x},${q.y}`,stroke:'#bb8e63','stroke-width':2},g);}node('text',{x:center.x,y:center.y-43,'text-anchor':'middle','font-size':11,fill:'#fff4d8'},g).textContent=t('goatShelter');}
/** @param {Element} parent @param {import('./goat-scene-snapshot.js').GoatRanchSnapshot} snapshot */
